-- v12 exercise how-tos: short numbered steps, form cues and photo file names per catalog exercise.
-- Steps are written from free-exercise-db (Unlicense, github.com/yuhonas/free-exercise-db) and
-- shortened; the mapping per key is in server/static/exercises/SOURCES.tsv. Photos live in
-- server/static/exercises and are embedded in the binary; images holds their file names in order
-- (start, end) and is empty where no source photo fits.

ALTER TABLE exercises
    ADD COLUMN steps  TEXT[] NOT NULL DEFAULT '{}',
    ADD COLUMN cues   TEXT[] NOT NULL DEFAULT '{}',
    ADD COLUMN images TEXT[] NOT NULL DEFAULT '{}',
    ADD CONSTRAINT exercises_howto_sizes CHECK (cardinality(steps) <= 8 AND cardinality(cues) <= 4 AND cardinality(images) <= 4);

UPDATE exercises e
SET steps = v.steps, cues = v.cues, images = v.images
FROM (VALUES
    ('incline_push_up', ARRAY['Place your hands on a bench or sturdy ledge, a little wider than your shoulders.', 'Step your feet back until your body is one straight line from head to heels.', 'Bend your elbows and lower your chest to the edge.', 'Press back up until your arms are straight.']::text[],
     ARRAY['Keep your hips level with your shoulders.', 'The lower the surface, the harder it gets.']::text[],
     ARRAY['incline_push_up-0.jpg', 'incline_push_up-1.jpg']::text[]),
    ('push_up', ARRAY['Start face down on the floor with your hands just wider than your shoulders and your arms straight.', 'Keep your body in one straight line from head to heels.', 'Lower yourself until your chest almost touches the floor.', 'Press back up to straight arms, squeezing your chest at the top.']::text[],
     ARRAY['Do not let your hips sag or pike up.', 'Elbows point back about 45 degrees, not out to the sides.']::text[],
     ARRAY['push_up-0.jpg', 'push_up-1.jpg']::text[]),
    ('decline_push_up', ARRAY['Place your feet on a bench or box and your hands on the floor, a little wider than your shoulders.', 'Hold your body in one straight line from head to heels.', 'Lower yourself until your chest almost touches the floor.', 'Press back up to straight arms.']::text[],
     ARRAY['Keep your core tight so your hips do not sag.', 'A higher box shifts more work to your shoulders.']::text[],
     ARRAY['decline_push_up-0.jpg', 'decline_push_up-1.jpg']::text[]),
    ('band_pull_up', ARRAY['Loop a resistance band around the pull-up bar and put one bent knee in the loop.', 'Hold the bar with a grip a little wider than your shoulders and hang with straight arms.', 'Pull your elbows down toward your sides until your chin is over the bar.', 'Pause, then lower yourself back to straight arms.']::text[],
     ARRAY['Avoid swinging or jerking.', 'A thicker band gives more help.']::text[],
     ARRAY['band_pull_up-0.jpg', 'band_pull_up-1.jpg']::text[]),
    ('negative_pull_up', ARRAY['Use a box or a jump to start with your chin over the bar and your hands a little wider than your shoulders.', 'Hold the top position for a moment with your chest up.', 'Lower yourself as slowly as you can, aiming for 3 to 5 seconds.', 'Hang with straight arms, then step down and reset.']::text[],
     ARRAY['Do not drop; control the whole way down.', 'Stop the set when you can no longer lower slowly.']::text[],
     ARRAY[]::text[]),
    ('pull_up', ARRAY['Hold the bar with your palms facing away, a little wider than your shoulders, and hang with straight arms.', 'Lean back slightly and push your chest out.', 'Pull your elbows down and back until the bar is near your upper chest.', 'Pause, then lower yourself slowly to straight arms.']::text[],
     ARRAY['Start each rep from a full hang.', 'Keep your body still; no kicking or swinging.']::text[],
     ARRAY['pull_up-0.jpg', 'pull_up-1.jpg']::text[]),
    ('chin_up', ARRAY['Hold the bar with your palms facing you, hands about shoulder width apart, and hang with straight arms.', 'Keep your torso straight and your chest up.', 'Pull until your chin is over the bar, keeping your elbows close to your body.', 'Pause, then lower yourself slowly to straight arms.']::text[],
     ARRAY['Think about pulling the elbows down to your ribs.', 'Do not swing or kick.']::text[],
     ARRAY['chin_up-0.jpg', 'chin_up-1.jpg']::text[]),
    ('inverted_row', ARRAY['Set a bar in a rack at about waist height and lie underneath it.', 'Grab the bar a little wider than your shoulders and hang with straight arms and your heels on the floor.', 'Keep your body straight and pull your chest to the bar.', 'Pause, then lower yourself to straight arms.']::text[],
     ARRAY['Squeeze your shoulder blades together at the top.', 'Walk your feet closer to make it easier.']::text[],
     ARRAY['inverted_row-0.jpg', 'inverted_row-1.jpg']::text[]),
    ('dead_hang', ARRAY['Hold a pull-up bar with your palms facing away, hands about shoulder width apart.', 'Step off so you hang with straight arms and your feet off the floor.', 'Keep a firm grip and let your shoulders stay slightly active, not shrugged to your ears.', 'Hang for the planned time, then step down.']::text[],
     ARRAY['Breathe steadily.', 'Stop before your grip fails so you can step down safely.']::text[],
     ARRAY[]::text[]),
    ('bench_dip', ARRAY['Sit on the edge of a bench and put your hands beside your hips, then slide your hips off the edge.', 'Straighten your arms with your legs out in front of you.', 'Bend your elbows to about 90 degrees, keeping your back close to the bench.', 'Press back up until your arms are straight.']::text[],
     ARRAY['Keep your elbows pointing back, not out.', 'Bend your knees to make it easier.']::text[],
     ARRAY['bench_dip-0.jpg', 'bench_dip-1.jpg']::text[]),
    ('dip', ARRAY['Grip two parallel bars and lift yourself to straight arms.', 'Lean slightly forward and keep your chest up.', 'Bend your elbows and lower until your upper arms are about parallel to the floor.', 'Press back up to straight arms.']::text[],
     ARRAY['Do not swing your legs.', 'Stop if your shoulders pinch at the bottom.']::text[],
     ARRAY['dip-0.jpg', 'dip-1.jpg']::text[]),
    ('air_squat', ARRAY['Stand with your feet about shoulder width apart and your toes slightly out.', 'Sit your hips back and bend your knees, keeping your chest and head up.', 'Lower as far as you can with your heels down, with your knees tracking over your toes.', 'Drive through your whole foot to stand back up.']::text[],
     ARRAY['Keep your heels on the floor.', 'Push your knees out, not in.']::text[],
     ARRAY['air_squat-0.jpg', 'air_squat-1.jpg']::text[]),
    ('split_squat', ARRAY['Stand with one foot a long step in front of the other, with your feet hip width apart.', 'Keep your torso upright and lower your back knee toward the floor.', 'Stop just above the floor with your front heel down.', 'Press through the front foot to stand up; finish all reps, then switch legs.']::text[],
     ARRAY['Your front knee stays over your foot.', 'Keep your feet in the same place for the whole set.']::text[],
     ARRAY[]::text[]),
    ('bulgarian_split_squat', ARRAY['Stand a long step in front of a bench and rest the top of one back foot on it.', 'Keep your torso upright with most of your weight on the front foot.', 'Lower your back knee toward the floor until your front thigh is about parallel.', 'Press through the front heel to stand; finish all reps, then switch legs.']::text[],
     ARRAY['Your front knee stays over your foot.', 'Find your step length in the first rep and keep it.']::text[],
     ARRAY[]::text[]),
    ('lunge', ARRAY['Stand tall with your feet hip width apart and your hands on your hips.', 'Step forward and lower your hips until your back knee nearly touches the floor.', 'Keep your front knee over your foot and your torso upright.', 'Push through the front heel to return to standing, then repeat on the other leg.']::text[],
     ARRAY['Take a long enough step that your front shin stays upright.', 'Do not let your front knee collapse inward.']::text[],
     ARRAY['lunge-0.jpg', 'lunge-1.jpg']::text[]),
    ('step_up', ARRAY['Stand facing a sturdy bench or step that puts your thigh about parallel when your foot is on it.', 'Place one foot fully on the step.', 'Push through that heel to stand up on the step.', 'Step back down with control; finish all reps, then switch legs.']::text[],
     ARRAY['Let the working leg do the lifting, not the push-off foot.', 'Holding dumbbells is optional.']::text[],
     ARRAY['step_up-0.jpg', 'step_up-1.jpg']::text[]),
    ('glute_bridge', ARRAY['Lie on your back with your knees bent and your feet flat, about hip width apart.', 'Push through your heels and lift your hips until your body is in a line from shoulders to knees.', 'Squeeze your glutes and hold for a second at the top.', 'Lower slowly to the floor.']::text[],
     ARRAY['Keep your ribs down; do not arch your lower back.', 'Push through your heels.']::text[],
     ARRAY['glute_bridge-0.jpg', 'glute_bridge-1.jpg']::text[]),
    ('single_leg_glute_bridge', ARRAY['Lie on your back with your feet flat and your knees bent.', 'Lift one leg and pull that knee toward your chest.', 'Push through the heel of the other foot to lift your hips as high as you can.', 'Lower slowly; finish all reps, then switch legs.']::text[],
     ARRAY['Keep your hips level, not tilted to one side.', 'Squeeze your glute at the top.']::text[],
     ARRAY['single_leg_glute_bridge-0.jpg', 'single_leg_glute_bridge-1.jpg']::text[]),
    ('good_morning', ARRAY['Stand with your feet about shoulder width apart, knees slightly bent, and your hands behind your head.', 'Push your hips back and lean your chest forward with a flat back.', 'Stop when your torso is near parallel to the floor or you feel your hamstrings stretch.', 'Drive your hips forward to stand tall.']::text[],
     ARRAY['Hinge at the hips; do not round your back.', 'Keep your knees softly bent and still.']::text[],
     ARRAY[]::text[]),
    ('calf_raise', ARRAY['Stand with the balls of your feet on the floor or the edge of a step, with your feet hip width apart.', 'Rise up as high as you can on your toes.', 'Pause for a second at the top.', 'Lower slowly until your heels are level or just below the step.']::text[],
     ARRAY['Keep your knees straight but not locked.', 'Use a wall for balance if you need it.']::text[],
     ARRAY[]::text[]),
    ('plank', ARRAY['Lie face down and prop yourself on your forearms, with your elbows right under your shoulders.', 'Lift your hips and rest on your toes.', 'Hold your body in one straight line from head to heels.', 'Hold for the planned time, breathing steadily.']::text[],
     ARRAY['Squeeze your glutes and brace your abs.', 'Do not let your hips sag or rise.']::text[],
     ARRAY['plank-0.jpg', 'plank-1.jpg']::text[]),
    ('side_plank', ARRAY['Lie on your side with your elbow under your shoulder and your legs stacked.', 'Lift your hips off the floor so your body is a straight line from head to feet.', 'Hold for the planned time, then switch sides.']::text[],
     ARRAY['Keep your hips high and your neck in line with your spine.', 'Bend your bottom knee to make it easier.']::text[],
     ARRAY['side_plank-0.jpg', 'side_plank-1.jpg']::text[]),
    ('hollow_hold', ARRAY['Lie on your back with your arms overhead and your legs straight.', 'Press your lower back into the floor.', 'Lift your shoulders and your straight legs a few inches off the floor.', 'Hold the shape for the planned time.']::text[],
     ARRAY['Keep your lower back flat on the floor.', 'Bend your knees or bring your arms to your sides to make it easier.']::text[],
     ARRAY[]::text[]),
    ('burpee', ARRAY['Stand with your feet shoulder width apart.', 'Squat down and place your hands on the floor, then jump or step your feet back to a push-up position.', 'Lower your chest to the floor, then press up.', 'Jump or step your feet back under your hips and jump up with your arms overhead.']::text[],
     ARRAY['Keep your core tight in the push-up position.', 'Step instead of jumping to make it easier.']::text[],
     ARRAY[]::text[]),
    ('goblet_squat', ARRAY['Hold a dumbbell upright against your chest with both hands, elbows pointing down.', 'Stand with your feet a little wider than your shoulders and your toes slightly out.', 'Squat down between your legs, keeping your chest and head up.', 'Pause at the bottom, then stand back up.']::text[],
     ARRAY['Use your elbows to push your knees out at the bottom.', 'Keep your heels on the floor.']::text[],
     ARRAY['goblet_squat-0.jpg', 'goblet_squat-1.jpg']::text[]),
    ('db_romanian_deadlift', ARRAY['Hold a dumbbell in each hand at your sides and stand with your feet about shoulder width apart.', 'Soften your knees and push your hips back as you lower the weights along your legs.', 'Stop when you feel a stretch in your hamstrings, with your back flat.', 'Drive your hips forward to stand tall.']::text[],
     ARRAY['Keep the weights close to your legs.', 'Hinge at the hips; your knees stay softly bent and still.']::text[],
     ARRAY['db_romanian_deadlift-0.jpg', 'db_romanian_deadlift-1.jpg']::text[]),
    ('db_bench_press', ARRAY['Lie on a flat bench with a dumbbell in each hand at the sides of your chest, palms facing forward.', 'Plant your feet on the floor and keep your shoulder blades pinched together.', 'Press the weights straight up until your arms are straight.', 'Lower slowly until your elbows are about 90 degrees.']::text[],
     ARRAY['Lower for about twice as long as you lift.', 'Keep your wrists straight over your elbows.']::text[],
     ARRAY['db_bench_press-0.jpg', 'db_bench_press-1.jpg']::text[]),
    ('db_row', ARRAY['Place one knee and the same-side hand on a bench, with your back flat and a dumbbell in your other hand.', 'Let the dumbbell hang at arm''s length.', 'Pull it up to the side of your chest, keeping your elbow close to your body.', 'Lower slowly; finish all reps, then switch sides.']::text[],
     ARRAY['Keep your torso still; the back does the work, not the arm.', 'Do not twist as you pull.']::text[],
     ARRAY['db_row-0.jpg', 'db_row-1.jpg']::text[]),
    ('db_overhead_press', ARRAY['Stand with your feet shoulder width apart and a dumbbell in each hand at shoulder height, palms forward.', 'Brace your core and squeeze your glutes.', 'Press the dumbbells straight up until your arms are straight.', 'Lower slowly back to your shoulders.']::text[],
     ARRAY['Do not lean back or use your legs.', 'Keep your ribs down.']::text[],
     ARRAY['db_overhead_press-0.jpg', 'db_overhead_press-1.jpg']::text[]),
    ('lateral_raise', ARRAY['Stand with a dumbbell in each hand at your sides and a slight bend in your elbows.', 'Raise your arms out to the sides until they are about parallel to the floor.', 'Pause for a second.', 'Lower slowly to your sides.']::text[],
     ARRAY['Use a light weight and do not swing.', 'Lead with your elbows, as if pouring water from a jug.']::text[],
     ARRAY['lateral_raise-0.jpg', 'lateral_raise-1.jpg']::text[]),
    ('biceps_curl', ARRAY['Stand with a dumbbell in each hand at your sides, palms facing forward.', 'Keep your elbows pinned to your sides.', 'Curl the weights up toward your shoulders.', 'Lower slowly until your arms are straight.']::text[],
     ARRAY['Keep your upper arms still.', 'Do not swing your body to lift the weight.']::text[],
     ARRAY['biceps_curl-0.jpg', 'biceps_curl-1.jpg']::text[]),
    ('triceps_extension', ARRAY['Stand with your feet shoulder width apart, holding one dumbbell with both hands overhead and your arms straight.', 'Keep your upper arms close to your head with your elbows pointing forward.', 'Bend your elbows to lower the dumbbell behind your head.', 'Straighten your arms to lift it back up.']::text[],
     ARRAY['Only your forearms move.', 'Brace your core so you do not arch your back.']::text[],
     ARRAY['triceps_extension-0.jpg', 'triceps_extension-1.jpg']::text[]),
    ('back_squat', ARRAY['Set the bar on a rack at just below shoulder height and step under it, with the bar across your upper back.', 'Lift it off the rack, step back, and set your feet about shoulder width apart.', 'Bend your hips and knees to lower until your thighs are about parallel to the floor.', 'Drive through your whole foot to stand back up.']::text[],
     ARRAY['Keep your chest up and your back flat.', 'Use a rack with safety bars set below your lowest point.']::text[],
     ARRAY['back_squat-0.jpg', 'back_squat-1.jpg']::text[]),
    ('deadlift', ARRAY['Stand with your feet hip width apart and the bar over your mid-foot.', 'Bend down and grip the bar just outside your legs, with your back flat and your chest up.', 'Push the floor away and stand up with the bar close to your legs.', 'Lower the bar along the same path, then reset.']::text[],
     ARRAY['Keep your back flat; do not round it.', 'Brace your core before each rep.']::text[],
     ARRAY['deadlift-0.jpg', 'deadlift-1.jpg']::text[]),
    ('bench_press', ARRAY['Lie on a flat bench with your eyes under the bar and your feet flat on the floor.', 'Grip the bar a little wider than your shoulders and unrack it over your chest.', 'Lower the bar to your mid-chest with control.', 'Press it back up until your arms are straight.']::text[],
     ARRAY['Keep your shoulder blades pinched and your feet planted.', 'Use safety bars or a spotter.']::text[],
     ARRAY['bench_press-0.jpg', 'bench_press-1.jpg']::text[]),
    ('overhead_press', ARRAY['Set the bar at chest height on a rack and grip it just wider than your shoulders.', 'Lift it off, step back, and hold it at your collarbone with your elbows slightly forward.', 'Squeeze your glutes and press the bar straight up until your arms are straight.', 'Lower it back to your collarbone with control.']::text[],
     ARRAY['Move your head back, then through, as the bar passes.', 'Do not lean back.']::text[],
     ARRAY['overhead_press-0.jpg', 'overhead_press-1.jpg']::text[]),
    ('hangboard_hang', ARRAY['Hold a large hangboard edge with an open hand or half crimp, fingers on the edge.', 'Step off the floor with your feet clear of the ground and your arms nearly straight.', 'Keep your shoulders engaged, not shrugged.', 'Hang for the planned time, then step down.']::text[],
     ARRAY['Start with a bigger edge and stay within your plan.', 'Stop at any sharp finger pain.']::text[],
     ARRAY[]::text[])
) AS v (key, steps, cues, images)
WHERE e.key = v.key AND e.user_id IS NULL;
